import functools
from fastapi import FastAPI, Depends
from fastapi.dependencies.utils import get_typed_signature
import inspect
from typing import ForwardRef

# Define a class to use for forward reference
class User:
    pass

def original_func(user: "User"):
    return user

@functools.wraps(original_func)
def wrapper_func(user: "User"):
    return original_func(user)

def test_wrapped_method_type_inference():
    # This should not raise NameError
    try:
        sig = get_typed_signature(wrapper_func)
        # Verify that the parameter 'user' has the correct type
        param = sig.parameters['user']
        assert param.annotation is User
        print("Test passed!")
    except NameError as e:
        print(f"Test failed with NameError: {e}")
        raise e
    except Exception as e:
        print(f"Test failed with exception: {e}")
        raise e

if __name__ == "__main__":
    test_wrapped_method_type_inference()
